# Spartacus (Warhammer Historical, 2006?) army lists: Spartacus's Slave Revolt, Late Republican Roman Consular Army, Sicilian Slave Revolt.
# Book page numbers are printed page numbers (pdf page - 2). Percentages are by points. Model stats order: M WS BS S T W I A Ld
import copy
from rb_data import M, U
LISTS = []; VAR = {}; AVAIL = []; UNAV = []; OPTAV = []; OPTRULE = []; OPTSTAT = []; RATIOS = []; OPT_ONCE = []; PAIRS = []
SECOND = {}; UNIT_MAX_IN = []; GEN = {}; COND_CHARS = []; COSTV = []; STATV = []; HIRDMEN_LE_BONDIR = []; EXCL = []
FLAT = []; PTSLIM = []; MODLIM = []
CH, SINF, SCAV, ART, GG = 'Characters', 'Slave Infantry', 'Cavalry', 'Artillery', 'Gallic and Germanic Slaves'
def variants(key, title, comps):
    VAR[key] = {}; out = []
    for c, (lim, txt) in comps.items():
        VAR[key][c] = f'Spartacus: {title}' if len(comps) == 1 else f'Spartacus: {title} - {c}'
        out.append((VAR[key][c], lim, txt))
    return out
def L(**kw):
    out = {}
    for k, v in kw.items():
        cat = k.replace('_', ' ')
        out[cat] = {'min': v[0], 'max': v[1]} if isinstance(v, tuple) and v[0] and v[1] < 100 else ({'min': v[0]} if isinstance(v, tuple) and v[0] else {'max': v[1] if isinstance(v, tuple) else v})
    return out

# ================================================================== SPARTACUS'S SLAVE REVOLT (book pp.12-14)
SR = []
GENLAB = 'Army General (+45 pts; Ld raised to 9 Heroic / 7 Tribal)'
SRC = [('Light armour', 3), ('Shield', 2), ('Large shield (on foot)', 4)]
SR.append(U(CH, 'Spartacus', [M('Spartacus', '5 6 5 4 4 3 6 3 10', 200, weapons=['Hand Weapon'], rules=['Army General', "I'm Spartacus!", 'All is lost!', 'Stealth', 'Hates Romans', 'Looting', 'Stubborn'], options=copy.deepcopy(SRC))],
    'Armed with a sword. May have light armour (+3 pts); shield (+2 pts), or large shield (+4 pts) if on foot. May ride a horse (free) - his Move rate increases to 8. Army General, "I\'m Spartacus!" and "All is lost!", Stealth, Hates Romans, Looting, Stubborn. 0-1. "I\'m Spartacus!": if Spartacus is in a unit and should lose his final wound, on a 4+ he is not really dead - he may be exchanged with another model in the unit and is left with one wound. If he is not in a unit and loses his final wound (or is killed/ran down in pursuit), on a roll of 6 he is not really dead but replaces the nearest friendly model and is left with one wound. "All is lost!": if Spartacus is finally killed the entire army must take a Leadership test with -1 to their Ld. Not available in the Germano-Gallic army.', mx=1, page='13'))
SR.append(U(CH, 'Heroic Leader', [M('Heroic Leader', '5 5 5 4 4 2 5 3 8', 85, weapons=['Hand Weapon'], rules=['Stealth', 'Hates Romans', 'Looting'], options=copy.deepcopy(SRC) + [('Stubborn', 3), (GENLAB, 45)])],
    'Armed with a sword. May have light armour (+3 pts), shield (+2 pts), large shield (+4 pts) if on foot. May ride a horse (free) - his Movement rate increases to 8. May be Stubborn (+3 pts). Stealth. Hates Romans. Looting. (Eg Crixus, Castus and Gannicus.) You must include at least one character to command the army. If you do not select Spartacus, or he is not available, a Heroic or Tribal leader may be made the General (+45 pts) and have their Ld raised to 9 or 7 respectively.', page='13'))
SR.append(U(CH, 'Tribal Leader', [M('Tribal Leader', '5 5 5 4 4 2 5 3 6', 70, weapons=['Hand Weapon'], rules=['Stealth', 'Hates Romans', 'Looting', 'Warband'], options=copy.deepcopy(SRC) + [('Stubborn', 3), (GENLAB, 45)])],
    'Armed with a sword. May have light armour (+3 pts), shield (+2 pts), large shield (+4 pts) if on foot. May ride a horse (free) - his Movement rate increases to 8. May be Stubborn (+3 pts). Stealth. Hates Romans. Looting. Tribal Leaders are subject to the rules for Warband. May be made the General (+45 pts, Ld raised to 7) if Spartacus is not taken.', page='13'))
SR.append(U(CH, 'Gladiators', [M('Gladiator', '5 4 4 3 3 1 4 2 8', 20, mn=1, weapons=['Hand Weapon'], rules=['Stealth', 'Hates Romans', 'Looting', 'Different Equipment'],
    options=[('Light armour', 2), ('Shield', 1), ('Large shield (replaces shield)', 1), ('Additional hand weapon', 2), ('Throwing spear', 2), ('Pilum', 4), ('Double-handed weapon', 3), ('Toughness 4', 5), ('Stubborn', 3)])],
    'Armed with a hand weapon. May have light armour (+2 pts), and shield (+1 pt) or large shield (+2 pts). May be armed with one of the following: additional hand weapon (+2 pts), throwing spear (+2 pts), pilum (+4 pts), or double-handed weapon (+3 pts). May increase Toughness to 4 (+5 pts). May be made Stubborn (+3 pts). Stealth. Hates Romans. Looting. Different Equipment. Up to eight Gladiators per 1,000 points (Early and Late armies; up to five in the Germano-Gallic army), pro rata rounding down. Upon deployment the player may deploy the Gladiators as a single unit of Light Infantry (at least five models, no Leader, Musician or Standard) or include them within other units to a maximum of two per unit; if deployed in other units they are subject to that unit\'s Leadership and psychology and may not leave. If joined by Spartacus the unit is immune to panic, fear and terror and may use his Leadership even in skirmish order. Victory points are gained for each Gladiator killed. (The option choices are per unit here; the book allows each Gladiator model to be armed differently.)', page='13'))
SR.append(U(SINF, 'Trained Slaves', [M('Slave', '4 3 3 3 3 1 3 1 7', 7, mn=5, weapons=['Hand Weapon', 'Shield'], rules=['Warband Psychology (rule 2)', 'Hates Romans', 'Looting', 'Stealth'],
    options=[('Large shield (replaces shield)', 2), ('Throwing spear (replaces mixed weapons)', 2), ('Stubborn', 3), ('Pilum (one unit; replaces mixed weapons)', 4), ('Light armour (one unit)', 3), ('Fiery Rollers (+40 pts; one unit)', 0)])],
    'Armed with mixed weapons and shield. Any unit may replace shields with large shields (+2 pts), mixed weapons with throwing spear (+2 pts), and may be Stubborn (+3 pts). One unit may replace mixed weapons with pilum (+4 pts). Up to one unit may have light armour (+3 pts). Subject to Warband Rule 2. Hates Romans. Looting. Stealth. There must be at least as many Untrained Slave models in the army as Trained Slaves (not enforced). May not be taken in the Germano-Gallic army. Any one of Gladiators, Trained Slaves, Gallic or Germanic Slaves may carry the Fiery Rollers (+40 pts).', page='13'))
SR.append(U(SINF, 'Untrained Slaves', [M('Untrained Slave', '4 2 2 3 3 1 2 1 5', 4, mn=5, weapons=['Improvised Weapon'], rules=['Light Troops', 'Warband Psychology (rules 1 & 2)', 'Hates Romans', 'Looting', 'Stealth'],
    options=[('Mixed weapons', 1), ('Throwing spear', 3), ('Shield', 1)])],
    'Armed with improvised weapons. May have mixed weapons (+1 pt) or throwing spear (+3 pts) and shield (+1 pt). Light Infantry. Subject to Warband Rules 1 and 2. Hates Romans. Stealth. Looting.', page='14'))
SR.append(U(SINF, 'Gallic and Germanic Slaves', [M('Gallic/Germanic Slave', '5 3 3 3 3 1 3 1 5', 6, mn=5, weapons=['Hand Weapon', 'Shield'], rules=['Warband', 'Looting', 'Hates Romans', 'Stealth'],
    options=[('Throwing spear', 2), ('Large shield (replaces shield)', 2), ('Stubborn', 3), ('Fiery Rollers (+40 pts; one unit)', 0)])],
    'Armed with mixed weapons and shield. May take throwing spear (+2 pts) and replace shields with large shields (+2 pts). May be Stubborn (+3 pts). Warband. Looting. Hate Romans. Stealth. These represent slaves from German and Gallic stock, fighting in their traditional way.', page='14'))
SR.append(U(SINF, 'Camp Followers', [M('Camp Follower', '4 2 2 3 3 1 2 1 5', 3, mn=5, weapons=['Dagger', 'Improvised Weapon'], rules=['Light Troops', "We'll take care of the rear!", 'Looting'])],
    'Armed with daggers, farm tools and other improvised weapons & rocks (count as javelin - 4" range). Light Infantry. "We\'ll take care of the rear!": units with this rule must be deployed together as the last units (prior to any character placement) to the rear of the army. Looting.', page='14'))
SR.append(U(SINF, 'Herdsmen', [M('Herdsman', '5 2 3 3 3 1 3 1 5', 4, mn=5, weapons=['Javelin'], rules=['Skirmishers (Spartacus)', 'Looting'],
    options=[('Buckler', 1), ('Shield (replaces buckler)', 0), ('Exchange javelins for sling (every second unit)', 1), ('Exchange javelins for short bow (every second unit)', 1)])],
    'Armed with javelins. May have buckler or shield (+1 pt), every second unit may replace javelins with sling (+1 pt) or short bow (+1 pt). Skirmishers. Looting.', page='14'))
SR.append(U(SCAV, 'Slave Cavalry', [M('Slave Cavalryman', '8 3 3 3 3 1 3 1 6', 16, mn=5, weapons=['Hand Weapon', 'Shield'], rules=['Light Troops'], options=[('Throwing spear', 2), ('Light armour (one unit)', 4)])],
    'Armed with mixed weapons and shield. May have throwing spear (+2 pts). One unit may have light armour (+4 pts). Light Cavalry.', page='14'))
def scorpion(price, crewpts, page, extra=''):
    return U(ART, 'Looted Light Bolt Thrower' if price == 40 else 'Light Bolt Thrower (Scorpion)', [M('Scorpion', '- - - - 6 2 - - -', price, key='machine', rules=['Bolt Thrower (Spartacus)']),
        M('Crew', '4 2 2 3 3 1 3 1 7' if price == 40 else '4 3 3 3 3 1 3 1 7', crewpts, mn=2, mx=3, key='crew', weapons=['Hand Weapon'], options=[('Light armour', 2)] if price == 30 else [])],
        'Each machine has a two or three man crew armed with swords. Bolt Thrower - see WAB rulebook: range 36", Strength 4/-1 per rank, no save, D3 wounds per hit.' + extra, page=page)
SR.append(scorpion(40, 0, '14', ' Looted artillery: one looted piece per 2,000 points (Early Revolt), per 1,000 points (Late Revolt); none in the Germano-Gallic army.'))
SRV = variants('SR', "Spartacus's Slave Revolt", {
 'Early Revolt Army': (L(Characters=30, **{'Slave_Infantry': (25, 100), 'Gallic_and_Germanic_Slaves': (25, 50), 'Cavalry': 15, 'Artillery': 100}), 'Commanded by Spartacus before the Gauls and Germans under Crixus split off (also the army Spartacus commanded between Crixus\'s death and the last separation of the Gauls and Germans). Characters up to 30% (may include Spartacus and up to eight Gladiators per 1,000 pts); Slave Infantry at least 25% and at least 25% and up to 50% of the points must be spent on Gallic and Germanic Slaves; Cavalry up to 15%; Artillery one looted piece per 2,000 pts.'),
 'Germano-Gallic Slave Army': (L(Characters=30, **{'Slave_Infantry': (50, 100), 'Gallic_and_Germanic_Slaves': (50, 100), 'Cavalry': 10}), 'The Germano-Gallic force that split off from the main slave army, first under Crixus then later commanded by Castus and Gannicus. Characters up to 30% (Spartacus may not be taken; up to five Gladiators per 1,000 pts); at least 50% of the points must be spent on Gallic and Germanic slaves (Slave Infantry at least 50%); may not take any Trained Slaves; Slave Cavalry up to 10%; no Artillery.'),
 'Late Revolt Army': (L(Characters=25, **{'Slave_Infantry': (50, 100), 'Gallic_and_Germanic_Slaves': 25, 'Cavalry': 20}), 'Commanded by Spartacus in his last battles against the Romans. Characters up to 25% (may take Spartacus and up to eight Gladiators per 1,000 pts); Slave Infantry at least 50% (up to 25% of the army may be Gallic or Germanic Slaves); Slave Cavalry up to 20%; Artillery one looted piece per 1,000 pts.')})
SR_NOTES = "SPARTACUS'S SLAVE REVOLT (Spartacus, pp.12-14). The minimum size of a unit is five infantry models or five cavalry models, with no upper limit; one model in each unit may be upgraded to a Leader (+5 pts), Standard Bearer (+5 pts) and Musician (+5 pts) unless mentioned otherwise. Special rules: HATE ROMANS: subject to the Hatred rules sections 2 and 3 but not 1 (re-roll misses in the first round of combat and must pursue towards Roman units). LOOTING: a Slave unit catching and destroying a fleeing Roman unit better equipped with shields and weapons may loot the bodies and continue the battle using that equipment instead (it does not include armour); if the Slave unit subsequently flees it loses the bonus equipment. LEADERSHIP & WARBAND PSYCHOLOGY: if a character that does not have Warband psychology joins a unit with Warband psychology, the unit must use either its own Ld or the character's Ld and add on the Warband rank bonus. STEALTH: may move through difficult ground and obstacles at a normal pace even if formed, but lose combat rank bonuses when fighting in difficult ground or across obstacles; may not march; must see their foe before charging. FIERY ROLLERS (0-1, 40 pts): one formed unit of Gladiators, Trained, Gallic or Germanic Slaves carries two rollers; it causes fear in its frontal facing; it may only move in open terrain; in its Shooting phase it may 'shoot' one or both rollers at an enemy unit (3D6\" from higher ground, 2D6\" on level ground, over clear ground); a roller reaching the enemy causes D6 Strength 4 hits with no armour save (Drilled units and skirmishers take a Ld test at -1 to avoid each); if the unit is charged to its front or charges, each roller causes D6 S4 hits; the rollers can only be used once."
LISTS.append(('SR', "Spartacus's Slave Revolt (Spartacus)", 'Slave_Revolt_Spartacus.cat', SR, SRV, SR_NOTES))
