# ================================================================== LATE REPUBLICAN ROMAN CONSULAR ARMY (book pp.15-17)
RC = []
LIC = 'Lictors (up to two with a Consul, one with a Praetor or Crassus; Fasces)'
RC.append(U(CH, 'Consul', [M('Consul', '4 5 5 3 3 3 5 2 9', 135, weapons=['Hand Weapon', 'Light Armour'], rules=['Army General'], options=[('Shield', 2)])],
    'Sword, light armour. May carry a shield (+2 pts). May ride a horse (free, his Movement increases to 8). A Roman Consul may have up to two Lictors who must remain in base contact with the Consul (if mounted it is assumed the Lictors can keep pace). Army General. 0-1.', mx=1, page='15'))
RC.append(U(CH, 'Marcus Licinius Crassus', [M('Crassus', '4 5 5 3 3 2 5 2 9', 160, weapons=['Hand Weapon', 'Light Armour'], rules=['Army General', 'Reputation', 'Wealthy'], options=[('Shield', 2)])],
    'Sword, light armour. May carry a shield (+2 pts). May ride a horse (free, his Movement increases to 8). Army General. Up to one Lictor can be taken in the same manner as a Consul. Reputation: at the start of the game Crassus may remove one legionary in ten (removed equally as possible across all legionary units rounding to the nearest ten); this allows all Roman Legionary units to re-roll failed Panic tests and, should a legion break and be caught from combat, the slaves cannot loot its equipment; once a re-rolled Panic test is also failed both benefits are lost (the re-roll may be made using the Lictor). Wealthy: at the start of the game Crassus may nominate and upgrade one Legionary unit to become Drilled and Stubborn at no additional points cost. 0-1.', mx=1, page='16'))
RC.append(U(CH, 'Lictors', [M('Lictor', '4 3 3 3 3 2 4 1 7', 30, weapons=['Hand Weapon'], rules=['Fasces'])],
    'Sword. Fasces: the Lictor carries the Fasces, which allows the Consul the following options once per Lictor during the game: (1) re-roll any Roman Leadership test once within 12" of the Consul; or (2) add +1 to any Roman combat resolution once within 12" of the Consul. Lictors may be captured in the same way as a unit standard or killed in hand-to-hand combat; either way each is worth an additional 200 Victory points. 0-2 Lictors (up to two with a Consul, one with a Praetor as General or with Crassus: not enforced).', mx=2, page='15'))
